// This file adds a ModifyPlan method to GRETunnelResource to prevent
// perpetual plan drift caused by missing UseStateForUnknown plan modifiers
// in the generated schema, and to normalize list attribute ordering.
//
// This file is NOT generated by Speakeasy and will not be overwritten.
// See docs/bugs/BUG-002-config-order-plan-drift.md for details.

package provider

import (
	"context"

	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
)

// Compile-time check that GRETunnelResource implements ModifyPlan.
var _ resource.ResourceWithModifyPlan = &GRETunnelResource{}

func (r *GRETunnelResource) ModifyPlan(ctx context.Context, req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	// Skip on create (no prior state) or destroy (null plan).
	if req.State.Raw.IsNull() || req.Plan.Raw.IsNull() {
		return
	}

	// Preserve Computed attributes that are unknown in plan but known in state.
	// The generated schema lacks UseStateForUnknown plan modifiers on these.
	preserveStateForUnknownInt32(ctx, req, resp, path.Root("tunnel_id"))
	preserveStateForUnknownString(ctx, req, resp, path.Root("notes"))
	preserveStateForUnknownString(ctx, req, resp, path.Root("source_type"))
	preserveStateForUnknownString(ctx, req, resp, path.Root("template"))
	preserveStateForUnknownString(ctx, req, resp, path.Root("vendor"))

	// Normalize list ordering for options.xff.xff_ip_list.
	normalizeStringListAttr(ctx, req, resp, path.Root("options").AtName("xff").AtName("xff_ip_list"))
}
